ROOT=Path(__file__).resolve().parents[1]; OUT=ROOT/'results/model_foundation'
SOURCES=[
 {'title':'Mitsuhashi et al. (2009), BodyParts3D','url':'https://doi.org/10.1093/nar/gkn613','role':'Visual anatomical surface reference; adult male atlas derived from TARO MRI with anatomical refinement. It does not measure the current subject or define the force solver.'},
 {'title':'MyoSim model library','url':'https://github.com/MyoHub/myo_sim','role':'Installed native full-body geometry, 416 muscle-tendon force elements and rigid-body dynamics; exact installed source hashes are in each manifest.'},
 {'title':'MyoArm / MoBL source lineage','url':'https://github.com/MyoHub/myo_sim/blob/main/myo_sim/models/arm/README.md','role':'Upper limb model lineage and post-conversion adjustments. It does not supply independently actuated thoracoscapular muscles in this assembled model.'},
 {'title':'MyoLeg / Rajagopal source lineage and known limitations','url':'https://github.com/MyoHub/myo_sim/blob/main/myo_sim/models/leg/README.md','role':'Lower-limb reference; installed README also reports differences in knee moment arms and inelastic tendon mechanics. These require direct checks before squat/jump interpretation.'},
 {'title':'MyoTorso / Constrained Lumbar Spine 210','url':'https://github.com/MyoHub/myo_sim/blob/main/myo_sim/models/torso/README.md','role':'Lumbar and abdominal actuator lineage. Its installed README flags torso passive-dynamics limitations; generic spine parameters are not individualized disc mechanics.'},
 {'title':'MuJoCo muscle length / force law','url':'https://mujoco.readthedocs.io/en/stable/modeling.html#muscles','role':'Muscle-tendon path length = fixed biological tendon length + variable fiber surrogate. Native active FLV gain and passive force are evaluated at the current length and velocity.'},
 {'title':'MuJoCo mechanics and friction cones','url':'https://mujoco.readthedocs.io/en/stable/computation/index.html','role':'Rigid-body equations, constraint-force mapping and friction mechanics. This project uses an explicit inverse-dynamics QP, not MuJoCo native contact simulation for OHP.'},
 {'title':'Seth et al. (2019), thoracoscapular shoulder','url':'https://doi.org/10.3389/fnbot.2019.00090','role':'Rationale for independent scapular movement and explicit trapezius/serratus action. This study supports choosing an appropriate shoulder mechanism, not the numerical force values of the current OHP.'},
 {'title':'Belli et al. (2023), GH stability / RMR','url':'https://doi.org/10.1371/journal.pone.0295003','role':'Joint stability can alter muscle allocation. The current model adopts a generic force-direction cone, without reproducing the paper’s activation-dynamics solver.'},
 {'title':'RMR v1.1 model and source code','url':'https://github.com/ComputationalBiomechanicsLab/rmr-solver/tree/v1.1','role':'Exact source of the audited unilateral thoracoscapular candidate. The source blob matches the local file byte for byte; source and model license are saved locally.'},
 {'title':'Dembia et al. (2020), OpenSim Moco','url':'https://doi.org/10.1371/journal.pcbi.1008493','role':'Reference for constrained trajectory optimization and compliant contact workflows. Moco has not been used to solve the current OHP, pull-up, muscle-up or jump.'},
 {'title':'BodyParts3D official license page','url':'https://lifesciencedb.jp/bp3d/info_en/license/index.html','role':'Official page states CC BY-SA 2.1 Japan. The base MyoHub asset states a different distribution license. Keep version/component evidence separate; do not infer one blanket license for every surface.'}
]

